INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ingin Bisa Bahasa Laos tapi Tidak Tahu Mulai dari Mana$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak orang Indonesia tertarik belajar bahasa Laos karena hubungan budaya dan pariwisata antarnegara ASEAN, tetapi bingung harus mulai dari mana. Hurufnya berbeda, nadanya asing di telinga, dan sumber belajar berbahasa Indonesia sangat terbatas. Kabar baiknya: untuk percakapan pertama, Anda hanya butuh sekitar 15 frasa sapaan dasar.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Karakteristik Bahasa Laos$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bahasa Laos (phasa Lao) adalah bahasa resmi Laos dan masih satu rumpun dengan bahasa Thai. Ia memakai aksara Lao yang mirip aksara Thai, dan merupakan bahasa bernada (tonal) dengan 6 nada. Namun untuk sapaan sehari-hari, orang Laos sangat menghargai usaha orang asing — pengucapan yang kurang sempurna pun biasanya tetap dipahami asal konteksnya jelas.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Perlu Disiapkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Aplikasi kamus Laos–Inggris/Indonesia di HP$$, $$Catatan kecil atau flashcard untuk 15 frasa inti$$, $$Video/audio pengucapan penutur asli (YouTube)$$, $$Partner latihan atau komunitas pecinta bahasa ASEAN$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah 1 dan 2: Sapaan Inti plus Kata Sopan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Sabaidee — halo / apa kabar (sapaan universal, dipakai pagi sampai malam)$$, $$Khop chai — terima kasih; khop chai lai lai — terima kasih banyak$$, $$Khor thod — maaf / permisi; la kone — selamat tinggal$$, $$Tambahkan kata sopan di akhir kalimat seperti yang dipakai lawan bicara — orang Laos menghargai usaha dan tidak tersinggung selama Anda tersenyum dan bersikap hormat$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Langkah 3 dan 4: Frasa Percakapan Mini dan Latihan Nada$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Frasa penting: 'Sabaidee, jao seu nyang?' (halo, siapa namamu?), 'Khoi seu ...' (nama saya ...), 'Jao sabai dee bor?' (apa kabarmu?), 'Sabai dee' (kabar baik). Bahasa Laos memiliki 6 nada; untuk pemula cukup ucapkan vokal dengan jelas dan tiru intonasi audio penutur asli — kesalahan nada pada sapaan dasar jarang menimbulkan salah paham karena konteks percakapan membantu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Risiko, Kesalahan Umum, dan Pemeriksaan Hasil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Kesalahan umum: mengucapkan 'sabaidee' terlalu cepat, lupa kata sopan sehingga terdengar kasar, langsung menghafal aksara Lao, dan takut salah sehingga tidak berani praktik. Checklist penyelesaian: Anda sudah bisa menyapa, memperkenalkan diri, berterima kasih, meminta maaf, dan pamit. Tindak lanjut: pelajari angka 1–10 dan frasa di restoran; target realistis percakapan dasar 2 menit dalam 30 hari latihan 15 menit sehari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Nyeri Siku yang Mengganggu Aktivitas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Nyeri pada siku bisa muncul tiba-tiba setelah aktivitas berat atau berkembang perlahan hingga mengganggu pekerjaan sehari-hari — mengetik, mengangkat barang, bahkan membuka pintu terasa sakit. Artikel ini membahas penyebab umumnya dan langkah penanganan mandiri yang aman.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Struktur Siku dan Penyebab Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Siku adalah sendi engsel yang menghubungkan lengan atas dengan lengan bawah, diperkuat tendon dan ligamen. Penyebab nyeri siku yang paling umum antara lain: tennis elbow (radang tendon sisi luar akibat gerakan berulang), golfer's elbow (sisi dalam), bursitis (radang kantung pelumas sendi), terkilir/cedera, serta radang sendi (arthritis).$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan: Yang Perlu Disiapkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Kompres dingin (es dibungkus handuk)$$, $$Perban elastis bila perlu$$, $$Obat pereda nyeri bebas yang biasa dipakai (sesuai aturan pakai)$$, $$Catatan: kapan nyeri mulai, aktivitas pemicu, dan skala nyeri 1–10$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah 1 sampai 3: Istirahat, Kompres, dan Posisi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pertama, hentikan aktivitas pemicu nyeri selama 2–3 hari dan hindari mengangkat beban berat dengan tangan yang sakit — gerakan ringan tanpa beban justru membantu sirkulasi. Kedua, tempelkan kompres dingin (es dibungkus handuk, jangan langsung ke kulit) 15–20 menit, 2–3 kali sehari pada 48 jam pertama; setelah itu boleh bergantian dengan kompres hangat. Ketiga, balut siku dengan perban elastis secukupnya (tidak sampai kesemutan) dan ganjal lengan dengan bantal saat tidur agar posisi siku sedikit lebih tinggi dari jantung.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Langkah 4 dan 5: Peregangan Ringan dan Kembali Beraktivitas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Setelah nyeri akut mereda (biasanya 3–5 hari), lakukan peregangan lembut: luruskan lengan, tekuk pergelangan ke bawah dengan tangan lain, tahan 15–30 detik, ulangi 3 kali — hentikan bila nyeri bertambah. Kembali ke aktivitas normal secara bertahap, perbaiki ergonomi (posisi keyboard, cara mengangkat barang, pemanasan sebelum olahraga), dan gunakan penyangga siku bila pekerjaan menuntut gerakan berulang.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Risiko, Tanda Bahaya, dan Catatan Penting$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Segera ke dokter bila: nyeri hebat setelah benturan dengan bentuk siku berubah; tidak bisa meluruskan atau menekuk siku sama sekali; mati rasa, kesemutan, atau tangan terasa dingin/pucat; bengkak tidak membaik setelah 1 minggu; atau demam disertai siku merah dan panas (tanda infeksi). Evaluasi setelah 1–2 minggu: nyeri berkurang dan aktivitas kembali normal. CATATAN: Artikel ini informasi umum, bukan pengganti nasihat medis — bila ragu, konsultasikan ke dokter atau fasilitas kesehatan terdekat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Ngarai?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Ngarai (canyon) adalah lembah dalam dan sempit dengan dinding curam, terbentuk oleh erosi sungai selama jutaan tahun. Berbeda dengan lembah biasa, ngarai memiliki dinding yang hampir vertikal — seperti luka raksasa yang diukir air pada permukaan bumi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Ngarai Terdalam di Dunia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Ngarai Cotahuasi di Peru mencapai kedalaman sekitar 3.354 meter — dua kali lipat Grand Canyon — dan tetangganya Ngarai Colca sedalam 3.270 meter, rumah bagi burung kondor Andes. Sementara itu Ngarai Yarlung Tsangpo di Tibet adalah yang terpanjang (sekitar 504 kilometer) dengan kedalaman maksimum sekitar 6.009 meter, tersembunyi di jantung Himalaya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Grand Canyon: Yang Paling Terkenal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Grand Canyon di Arizona, Amerika Serikat, sedalam sekitar 1.857 meter dan panjang 446 kilometer. Sungai Colorado mengukirnya selama 5–6 juta tahun, menyingkap lapisan batuan berusia hingga 2 miliar tahun — seperti membaca buku sejarah bumi dari samping.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Bagaimana Ngarai Terbentuk?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Tiga proses utama: erosi sungai yang mengikis dasar lembah, pelapukan dinding oleh angin dan hujan, serta pengangkatan tektonik yang membuat sungai terus mengukir ke bawah — butuh jutaan tahun. Ngarai juga menciptakan iklim mikro: Grand Canyon memiliki 5 zona vegetasi berbeda dari dasar hingga puncak, setara perjalanan dari gurun Meksiko hingga hutan Kanada dalam satu tebing.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Ngarai di Indonesia dan Pelestariannya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Indonesia punya Ngarai Sianok di Bukittinggi (15 km, kedalaman sekitar 120 meter) dan Ngarai Harau dengan tebing granit 100–500 meter yang menjadi surga panjat tebing. Ngarai terancam bendungan, pariwisata berlebihan, dan perubahan iklim — banyak yang kini dilindungi sebagai taman nasional. Bila berkunjung: patuhi jalur resmi, jangan membuang sampah, bawa air cukup, dan hormati situs budaya masyarakat adat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Angin sebagai Sumber Energi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Angin adalah udara yang bergerak karena perbedaan tekanan atmosfer akibat pemanasan matahari. Manusia memanfaatkannya sejak ribuan tahun: kincir angin pertama tercatat di Persia sekitar abad ke-9 untuk menggiling gandum, dan di Belanda abad pertengahan ribuan kincir memompa air dari polder. Prinsipnya sama hingga kini: mengubah energi kinetik angin menjadi energi mekanik.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Cara Kerja Turbin Angin Modern$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bilah turbin menangkap angin dan berputar, memutar poros yang terhubung ke generator melalui gearbox. Satu turbin modern berkapasitas 3–5 megawatt — cukup untuk listrik sekitar 2.000–3.000 rumah — dengan bilah sepanjang 80 meter. Tiga bagian utama: rotor (bilah + hub) yang menangkap angin, nacelle berisi gearbox dan generator, dan menara setinggi 80–120 meter agar mencapai angin yang lebih kencang; sistem yaw memutar nacelle mengikuti arah angin otomatis.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Turbin Darat vs Lepas Pantai$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Turbin lepas pantai (offshore) lebih besar dan mendapat angin lebih kencang serta konsisten, tetapi biaya pembangunan dan perawatannya jauh lebih mahal. Turbin darat (onshore) lebih murah namun sering menghadapi penolakan warga karena kebisingan dan pemandangan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Kelebihan dan Tantangan Energi Angin$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Kelebihannya: bersih tanpa emisi saat beroperasi, biaya operasi rendah, lahan di bawah turbin tetap bisa dipakai bertani, dan harga listrik angin turun lebih dari 70 persen dalam satu dekade. Tantangannya: angin tidak selalu bertiup sehingga butuh penyimpanan energi, berisik bagi warga sekitar, dapat mengganggu burung, dan bilah raksasanya sulit didaur ulang — meski teknologi daur ulangnya kini berkembang pesat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Potensi di Indonesia dan Masa Depan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Indonesia memiliki PLTB Sidrap di Sulawesi Selatan (75 MW, terbesar di Asia Tenggara saat diresmikan 2018) dan PLTB Tolo di Jeneponto; potensi terbaik ada di pesisir selatan Jawa, Nusa Tenggara, dan Sulawesi. Riset kini mengarah ke turbin apung lepas pantai, layang-layang pembangkit, dan turbin 15–20 MW — kombinasi angin + surya + baterai bisa menjadi kunci listrik bersih untuk daerah kepulauan terpencil.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$$Menjelaskan latar belakang lahirnya Sumpah Pemuda$$, $$Menyebutkan isi tiga ikrar Sumpah Pemuda 1928$$, $$Mengidentifikasi tokoh-tokoh Kongres Pemuda II$$, $$Menganalisis makna Sumpah Pemuda bagi persatuan bangsa$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Latar Belakang: Dari Kedaerahan Menuju Persatuan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Awal abad ke-20, organisasi pemuda di Hindia Belanda masih bersifat kedaerahan: Jong Java, Jong Sumatranen Bond, Jong Celebes, Jong Ambon, dan lainnya. Para pemuda menyadari perpecahan ini melemahkan perjuangan, sehingga muncul gagasan persatuan. Kongres Pemuda I (1926) di Jakarta baru menghasilkan kesepakatan awal tentang pentingnya persatuan — menjadi pemanasan menuju pertemuan yang lebih menentukan dua tahun kemudian.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Kongres Pemuda II (27–28 Oktober 1928)$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Kongres kedua dihadiri pemuda dari berbagai daerah dan organisasi. Dipimpin Sugondo Djojopuspito, dengan Mohammad Yamin sebagai perumus ikrar. Pada penutupan 28 Oktober 1928 dibacakan ikrar Sumpah Pemuda, diiringi lagu Indonesia Raya ciptaan W.R. Supratman yang pertama kali diperdengarkan. Tokoh penting lainnya: Amir Sjarifuddin, Siti Sundari, dan para wakil organisasi kedaerahan yang dengan lapang dada meleburkan identitas daerah demi Indonesia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Isi Sumpah Pemuda$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Pertama: Kami putra dan putri Indonesia, mengaku bertumpah darah yang satu, tanah air Indonesia$$, $$Kedua: Kami putra dan putri Indonesia, mengaku berbangsa yang satu, bangsa Indonesia$$, $$Ketiga: Kami putra dan putri Indonesia, menjunjung bahasa persatuan, bahasa Indonesia$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Makna Sumpah Pemuda$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Sumpah Pemuda adalah tonggak lahirnya kesadaran kebangsaan Indonesia: satu tanah air, satu bangsa, satu bahasa. Ia membuktikan bahwa persatuan bisa dibangun di atas keberagaman — pelajaran yang tetap relevan hingga kini.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal, Kunci Jawaban, dan Rangkuman$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Soal: (1) Sebutkan tiga isi ikrar Sumpah Pemuda! (2) Siapa perumus naskah dan pencipta lagu Indonesia Raya? (3) Mengapa Sumpah Pemuda dianggap tonggak persatuan bangsa? Kunci: (1) Satu tanah air, satu bangsa, satu bahasa Indonesia; (2) Mohammad Yamin dan W.R. Supratman; (3) Karena pertama kalinya pemuda lintas daerah berikrar sebagai satu bangsa Indonesia. Rangkuman: Sumpah Pemuda 28 Oktober 1928 lahir dari kesadaran pemuda lintas daerah untuk bersatu — tiga ikrarnya menjadi fondasi identitas nasional yang kita warisi hingga hari ini.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$$Menyebutkan pertempuran penting dalam mempertahankan kemerdekaan$$, $$Mengidentifikasi tokoh pejuang kemerdekaan$$, $$Menjelaskan makna perjuangan bagi bangsa Indonesia$$, $$Menunjukkan sikap menghargai jasa para pahlawan$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Setelah Merdeka, Perjuangan Belum Selesai$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Setelah Proklamasi 17 Agustus 1945, Belanda ingin kembali menjajah Indonesia dengan membonceng tentara Sekutu. Rakyat Indonesia pun berjuang mempertahankan kemerdekaan melalui pertempuran di berbagai daerah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Pertempuran 10 November 1945 di Surabaya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Pertempuran terbesar terjadi di Surabaya. Rakyat yang dipimpin Bung Tomo melalui radio berani melawan tentara Sekutu yang bersenjata lengkap; peristiwa heroik ini diperingati sebagai Hari Pahlawan setiap 10 November. Tokoh lain: Jenderal Sudirman (panglima besar yang bergerilya dalam keadaan sakit), I Gusti Ngurah Rai (Puputan Margarana di Bali), Sri Sultan Hamengku Buwono IX, dan ribuan pejuang tanpa nama.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Pertempuran Lain dan Cara Rakyat Berjuang$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pertempuran penting lainnya: Ambarawa di bawah Jenderal Sudirman (Desember 1945), Bandung Lautan Api (24 Maret 1946 — rakyat membakar kota agar tidak dikuasai musuh), Pertempuran Medan Area, dan Serangan Umum 1 Maret 1949 di Yogyakarta yang membuktikan TNI masih ada. Tidak hanya dengan senjata: rakyat menjadi kurir, menyediakan makanan, merawat pejuang yang luka, dan menyebarkan berita lewat radio — kemerdekaan adalah hasil kerja sama seluruh rakyat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Makna Perjuangan bagi Kita$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Kemerdekaan yang kita nikmati dibayar dengan darah dan air mata. Cara kita menghargainya: belajar sungguh-sungguh, rukun dengan teman, menjaga kebersihan lingkungan, dan mencintai tanah air.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal, Kunci Jawaban, dan Rangkuman$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Soal: (1) Pertempuran besar di Surabaya terjadi tanggal berapa dan diperingati sebagai hari apa? (2) Siapa panglima besar TNI yang memimpin Pertempuran Ambarawa? (3) Apa yang dimaksud Bandung Lautan Api? (4) Sebutkan dua cara menghargai jasa pahlawan! Kunci: (1) 10 November 1945 — Hari Pahlawan; (2) Jenderal Sudirman; (3) Rakyat Bandung membakar kota pada 24 Maret 1946 agar tidak dikuasai Sekutu/Belanda; (4) Contoh: belajar rajin, rukun dengan teman, upacara bendera dengan khidmat. Rangkuman: pertempuran Surabaya, Ambarawa, Bandung Lautan Api, dan Serangan Umum 1 Maret membuktikan tekad bangsa Indonesia mempertahankan kemerdekaan hingga akhirnya diakui dunia.$$));
